    private static function reviewQueue(PDO $db,int $productionId=0,int $formId=0):array
    {
        // Use assignment status, the same source counted by Readiness and Form Management.
        // A missing or inconsistent submission must remain visible but cannot be approved.
        $sql="SELECT fa.id assignment_id,fs.id,fs.status submission_status,fs.submitted_at,fs.submitted_by_user_id,f.id form_id,f.review_required,f.title,f.form_type,COALESCE(fa.subject_user_id,fa.user_id) subject_user_id,CONCAT(subject.first_name,' ',subject.last_name) subject_name,CONCAT(submitter.first_name,' ',submitter.last_name) submitter_name,p.title production_title FROM form_assignments fa JOIN forms f ON f.id=fa.form_id AND f.active=1 JOIN users subject ON subject.id=COALESCE(fa.subject_user_id,fa.user_id) AND subject.active=1 AND subject.account_status<>'disabled' LEFT JOIN form_submissions fs ON fs.assignment_id=fa.id LEFT JOIN users submitter ON submitter.id=fs.submitted_by_user_id LEFT JOIN productions p ON p.id=fa.production_id WHERE fa.status='requires_review'";
        $params=[];
        if($productionId>0){$sql.=" AND fa.production_id=:production";$params['production']=$productionId;}
        if($formId>0){$sql.=" AND f.id=:form";$params['form']=$formId;}
        $stmt=$db->prepare($sql." ORDER BY fs.submitted_at,fa.id");
        $stmt->execute($params);return $stmt->fetchAll();
    }

