        header('Content-Type:text/html; charset=utf-8');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Forms review · CTSMD Connect</title><link rel="stylesheet" href="<?=$u('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/unified-navigation.css')?>"><link rel="stylesheet" href="<?=$u('/assets/css/family-forms.css')?>"><?php WorkspaceUI::operationsStyles($basePath); ?><?php MemberUI::styles($basePath); ?></head><body class="app-body ux-operations ux-workspace ux-operational ux-forms<?=MemberUI::bodyClass()?>"><a class="ux-skip" href="#ux-main">Skip to main content</a><div class="unified-shell"><?php AppNavigation::renderSidebar('/admin/forms',$basePath,$user);?><main class="unified-main" id="ux-main" tabindex="-1"><?php AppNavigation::renderHeader('Forms','Review queue',$basePath,$sub); MemberUI::wayfinding($basePath);?><div class="ff-page ops-page"><?php if($flash):?><div role="status" class="ff-flash <?=$e($flash['type'])?>"><?=$e($flash['message'])?></div><?php endif;?><section class="ff-hero"><div><small>STAFF REVIEW</small><h2>Forms awaiting review</h2><p>Pending assignment records are shown here, including ones whose submission records need investigation.</p></div><div><b><?=count($rows)?></b><span>awaiting review</span></div></section><?php if($productionId||$formId):?><p><a href="<?=$u('/admin/forms')?>">← Show all pending reviews</a></p><?php endif;?><?php if(!$rows):?><section class="ff-empty"><h3>Nothing is waiting for review.</h3><p>No outstanding review assignments match this selection.</p></section><?php else:?><section class="ff-list"><?php foreach($rows as $row):$valid=(int)($row['id']??0)>0 && $row['submission_status']==='submitted' && (bool)$row['review_required'] && (int)$row['submitted_by_user_id']>0 && $row['submitter_name']!==null;$onBehalf=(int)$row['submitted_by_user_id']!==(int)$row['subject_user_id'];?><a class="ff-row" href="<?=$u($valid?'/admin/forms/review?id='.(int)$row['id']:'/admin/forms/review?assignment_id='.(int)$row['assignment_id'])?>"><div class="ff-person"><small>FOR</small><b><?=$e((string)$row['subject_name'])?></b></div><div class="ff-main"><small><?=$row['production_title']?$e((string)$row['production_title']):'CTSMD'?> · <?=$e(strtoupper(str_replace('_',' ',(string)$row['form_type'])))?></small><h3><?=$e((string)$row['title'])?></h3><p><?php if($row['submitter_name']):?>Submitted by <?=$e((string)$row['submitter_name'])?><?=$onBehalf?' · guardian/on behalf':''?><?php else:?>Submission record unavailable<?php endif;?><?php if($row['submitted_at']):?> · <?=date('M j, Y · g:i A',strtotime((string)$row['submitted_at']))?><?php endif;?></p><?php if(!$valid):?><p>Needs investigation: assignment awaits review but its submission cannot be approved. No automatic status change was made.</p><?php endif;?></div><span class="ff-status"><?=$valid?'Review →':'Inspect →'?></span></a><?php endforeach;?></section><?php endif;?></div></main></div><script src="<?=$u('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
