    private static function inspectAssignment(PDO $db,int $id):?array
    {
        if($id<1)return null;
        $stmt=$db->prepare("SELECT fa.id assignment_id,fa.status assignment_status,fa.production_id,fs.id submission_id,fs.status submission_status,fs.submitted_at,fs.submitted_by_user_id,f.id form_id,f.title,f.review_required,f.completion_mode,COALESCE(fa.subject_user_id,fa.user_id) subject_user_id,CONCAT(subject.first_name,' ',subject.last_name) subject_name,CONCAT(submitter.first_name,' ',submitter.last_name) submitter_name,p.title production_title FROM form_assignments fa JOIN forms f ON f.id=fa.form_id JOIN users subject ON subject.id=COALESCE(fa.subject_user_id,fa.user_id) LEFT JOIN form_submissions fs ON fs.assignment_id=fa.id LEFT JOIN users submitter ON submitter.id=fs.submitted_by_user_id LEFT JOIN productions p ON p.id=fa.production_id WHERE fa.id=:id LIMIT 1");
        $stmt->execute(['id'=>$id]);return $stmt->fetch()?:null;
    }

