        if($id<1)return null;$s=$db->prepare("SELECT fs.*,f.title,f.form_type,f.review_required,fa.status assignment_status,COALESCE(fa.subject_user_id,fa.user_id) subject_user_id,CONCAT(subject.first_name,' ',subject.last_name) subject_name,CONCAT(submitter.first_name,' ',submitter.last_name) submitter_name,p.title production_title FROM form_submissions fs JOIN form_assignments fa ON fa.id=fs.assignment_id JOIN forms f ON f.id=fs.form_id JOIN users subject ON subject.id=COALESCE(fa.subject_user_id,fa.user_id) JOIN users submitter ON submitter.id=fs.submitted_by_user_id LEFT JOIN productions p ON p.id=fa.production_id WHERE fs.id=:id LIMIT 1");$s->execute(['id'=>$id]);return$s->fetch()?:null;
    }

