    private static function csrf():void{if(!hash_equals((string)($_SESSION['family_forms_csrf']??''),(string)($_POST['csrf_token']??'')))throw new RuntimeException('Your session token expired. Please try again.');}
    private static function audit(PDO $db,int $actor,string $event,string $type,int $id,string $summary,array $meta):void{$s=$db->prepare('INSERT INTO audit_events (actor_user_id,event_type,subject_type,subject_id,summary,metadata_json) VALUES (:actor,:event,:type,:id,:summary,:meta)');$s->execute(['actor'=>$actor,'event'=>$event,'type'=>$type,'id'=>$id,'summary'=>$summary,'meta'=>json_encode($meta,JSON_THROW_ON_ERROR)]);}
    private static function notify(PDO $db,int $recipient,string $type,int $source,string $title,string $body,string $path):void{$s=$db->prepare('INSERT INTO app_notifications (recipient_user_id,source_type,source_id,title,body,action_path) VALUES (:recipient,:type,:source,:title,:body,:path)');$s->execute(['recipient'=>$recipient,'type'=>$type,'source'=>$source,'title'=>$title,'body'=>$body,'path'=>$path]);}
    private static function flash(string $type,string $message):void{$_SESSION['family_forms_flash']=['type'=>$type,'message'=>$message];}
    private static function takeFlash():?array{$v=$_SESSION['family_forms_flash']??null;unset($_SESSION['family_forms_flash']);return is_array($v)?$v:null;}
    private static function redirect(string $url):never{header('Location: '.$url,true,303);exit;}
    private static function forbidden():never{http_response_code(403);exit('Forms management permission is required.');}
    private static function notFound():never{http_response_code(404);exit('Form assignment not found or not available to this account.');}
